    if(!runtime_.ready() || failed_ || !world_ || !setupApplied_ || mainAttempted_ || !unitRecoveryIncomplete_ || !unitCoreFinished_ || runtime_.threadCount() || !runtime_.inspectExecutions().empty() || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty() || liveObjects(NativeKind::Event))throw std::runtime_error("Unit animation restore requires completed core before events");Binary in(openSnapshot(bytes,budget));in.expect(tag("SUAN"));auto version=in.u32();if((version!=1 && version!=2) || snapshotText(in,64)!=world_->resources().mapDigest())throw std::runtime_error("Unit animation snapshot map mismatch");auto time=std::bit_cast<double>(snapshotU64(in));if(!std::isfinite(time) || time!=simulationTime_)throw std::runtime_error("Unit animation snapshot clock mismatch");auto count=in.count(4,65536);if(count!=units_.size() || (count && !decodeHandle))throw std::runtime_error("Unit animation mapping count differs");std::vector<std::pair<std::uint32_t,AnimationState>> saved;saved.reserve(count);std::set<std::uint32_t> stableIds,targets;
